from pathlib import Path
import hashlib,json
root=Path.cwd()
prod=Path.home()/"prediction_research_prod"

def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def j(p):
    if not p.is_file() or p.is_symlink(): return {}
    try:
        x=json.loads(p.read_text())
        return x if isinstance(x,dict) else {}
    except Exception: return {}

files={
"supervisor":"control/codex_supervisor/supervisor.py",
"report":"control/hourly/candidate_reporting.py",
}
diff=[]
for k,rel in files.items():
    a=root/rel;b=prod/rel
    if (not a.is_file()) or (not b.is_file()) or b.is_symlink() or sha(a)!=sha(b):
        diff.append(k)

mapping={
"candidate_dispatch.py_sha256":"control/codex_supervisor/candidate_dispatch.py",
"candidate_policy_sha256":"control/hourly/candidate_queue.py",
"evidence_wake.py_sha256":"control/codex_supervisor/evidence_wake.py",
"build_wake.py_sha256":"control/codex_supervisor/build_wake.py",
"model_quality_gate.py_sha256":"control/codex_supervisor/model_quality_gate.py",
"astra_review_wake.py_sha256":"control/codex_supervisor/astra_review_wake.py",
"measurement_wake.py_sha256":"control/codex_supervisor/measurement_wake.py",
"supervisor_sha256":"control/codex_supervisor/supervisor.py",
"astra_autonomous_review.py_sha256":"control/codex_supervisor/astra_autonomous_review.py",
}
cfg=j(prod/"knowledge/codex_runtime/CONFIG.json")
bad=[]
for key,rel in mapping.items():
    p=prod/rel
    if (not p.is_file()) or p.is_symlink() or cfg.get(key)!=sha(p):
        bad.append(key.replace(".py_sha256","").replace("_sha256",""))
head="?"
git=prod/".git"
print("REPAIR_COMPACT="+json.dumps({"diff":diff,"bad_pins":bad},separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(0)
